'use strict';
const KEY='strato-trade-experience-2', APY=.097, POOLAPY=.1201;
let PRICE=StratoMarket.price,hoveringPrice=false,lastQuoteRefresh=0;
const initial={wallet:null,available:0,staked:0,usdst:0,rewards:0,rewardStart:Date.now(),history:[],unbond:[],lp:0,slippage:.5,network:'Base',amount:250,phase:0,allowance:0,bridged:0};
let s;try{s={...initial,...JSON.parse(localStorage.getItem(KEY)||'null')}}catch{s={...initial}}
const query=new URLSearchParams(location.search),variant='direct';
let pickerSide='pay';
let theme=query.get('theme')||localStorage.getItem('strato-theme')||'light',fundingFilter='All';
let page=location.hash.slice(1)==='home'?'trade':location.hash.slice(1)||'trade',period='1D',chartStyle='candle',advancedTab='pools',projectionMonths=12,stakeAmount=1000,orderMode='buy',busy=false,connectionNext=null,stakeMode='stake',lastFocus=null,operation=0;
const $=q=>document.querySelector(q),num=(n,d=2)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}),money=n=>'$'+num(n),escapeHTML=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',external:'M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7',shield:'m12 3-8 3v6c0 5 8 9 8 9s8-4 8-9V6Zm-4 9 3 3 5-6',gas:'M4 3h10v18H4ZM4 9h10m0-4 5 4v8c0 3 3 3 3 0V9l-3-3',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M9 15v6',line:'m3 17 5-7 5 3 8-9',candle:'M6 3v18m0-13h4v8H4V8ZM18 2v20m-3-17h6v9h-6Z',wallet:'M3 5h17v16H3ZM3 5V3h14v2m-2 7h7v5h-7Z',stake:'m12 3 8 5v8l-8 5-8-5V8ZM4 8l8 5 8-5m-8 5v8',receive:'M12 3v14m-5-5 5 5 5-5M4 18v3h16v-3',send:'M12 21V7m-5 5 5-5 5 5M4 6V3h16v3',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',plus:'M12 4v16M4 12h16',swap:'M4 7h15m-5-5 5 5-5 5M20 17H5m5-5-5 5 5 5',copy:'M8 8h13v13H8ZM3 16V3h13',globe:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M3 12h18M12 3c-6 6-6 12 0 18 6-6 6-12 0-18'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.shield}"/></svg>`}
function img(n,alt='',cls=''){const isStrato=n==='token-strato.png';if(isStrato&&theme==='dark')n='strato-symbol-white.svg';return `<img ${isStrato?'data-strato="true" ':''}src="assets/${n}" alt="${alt}"${cls?` class="${cls}"`:''}>`}
window.STRATO_ASSET_URL=n=>typeof EMBEDDED_ASSETS!=='undefined'&&EMBEDDED_ASSETS[n]||'assets/'+n;
const token=()=>img('token-strato.png','STRATO'),stable=()=>img('token-usdst.png','USDST'),usdc=()=>img('token-usdc.png','USDC');
function walletAsset(){return s.wallet==='MetaMask'?'metamask.svg':s.wallet==='WalletConnect'?'walletconnect.svg':'token-strato.png'}
function persist(){localStorage.setItem(KEY,JSON.stringify(s));$('#wallet-button').innerHTML=s.wallet?img(walletAsset(),'')+'0x71c…4F2a':'Connect Wallet';$('#wallet-button').classList.toggle('connected',!!s.wallet)}
function rewards(){return s.rewards+s.staked*APY*(Date.now()-s.rewardStart)/(365.25*86400000)}
function settleRewards(){s.rewards=rewards();s.rewardStart=Date.now()}
function recordActivity(type,amount,asset='STRATO'){s.history.unshift({type,amount,asset,time:Date.now(),id:Date.now().toString(16)});s.history=s.history.slice(0,30);persist()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function heading(t){return `<div class="modal-head"><h2 id="dialog-title">${t}</h2><button class="close" data-action="close" aria-label="Close">×</button></div>`}
function modal(html){lastFocus=document.activeElement;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();else $('#modal').scrollTop=0}
function closeModal(){if(busy)return;$('#modal').close();lastFocus?.focus?.()}
function go(p){closeModal();if(location.hash==='#'+p){page=p;render()}else location.hash=p;window.scrollTo({top:0,behavior:'smooth'})}
function dataRow(a,b){return `<div class="data-row"><span>${a}</span><strong>${b}</strong></div>`}
function periodButtons(values=['1H','1D','1W','1M','1Y','ALL']){return `<div class="periods">${values.map(t=>`<button data-period="${t}" class="${period===t?'active':''}" aria-pressed="${period===t}">${t}</button>`).join('')}</div>`}
function source(){return StratoFunding.get(s.sourceId)}
function hasAllowance(){return s.allowanceSource===source().id&&s.allowance>=s.amount}
function assetRate(a){return StratoSwap.rate(a,s.phase>0&&s.phase<4?s.quotePrice||PRICE:PRICE)}
function output(){return StratoFunding.get(s.outputId||'strato-strato')}
function sourceQty(){return Number.isFinite(s.payQuantity)?s.payQuantity:s.amount/assetRate(source())}
function receiveQty(){return s.amount/assetRate(output())}
function refreshAmount(){s.amount=sourceQty()*assetRate(source())}
function changePair(fromId,toId,quantity){s.sourceId=fromId;s.outputId=toId;s.phase=0;s.allowance=0;s.swapQuote=null;s.payQuantity=quantity;refreshAmount();persist();closeModal();render()}
function reversePair(){refreshAmount();const from=output(),to=settlement(),qty=receiveQty();changePair(from.id,to.id,qty)}
function sourceBalance(){return balanceOf(source())}
function quantityDecimals(asset){return ['USDC','USDT','USDST','cbDOGE','BOOE'].includes(asset)?2:6}
function assetQuantity(q,asset=source().asset){return Number(q||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:quantityDecimals(asset)})}
function sourceToken(){return img(source().icon,source().asset)}
function setTheme(value){theme=value==='dark'?'dark':'light';document.documentElement.dataset.theme=theme;document.querySelectorAll('img[data-strato]').forEach(i=>i.src=window.STRATO_ASSET_URL(theme==='dark'?'strato-symbol-white.svg':'token-strato.png'));localStorage.setItem('strato-theme',theme);const b=$('#theme-button');if(b){b.innerHTML=theme==='dark'?'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/></svg>':'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/></svg>';b.setAttribute('aria-label',theme==='dark'?'Switch to light theme':'Switch to dark theme')}}
function tradeBanner(){return `<section class="trade-banner"><div><span class="banner-ticker">$STRATO.</span><h1>Powering the financial infrastructure<br>for millions in hard assets.</h1></div><div class="banner-tokens" aria-hidden="true">${img('strato-symbol-white.svg','')}${img('strato-symbol-white.svg','')}</div></section>`}
function contractChip(a,full=true){if(!a.address)return `<span class="native-contract">Native asset · ${escapeHTML(a.network)}</span>`;return `<button class="token-contract" data-copy-address="${a.address}" data-copy-token="${escapeHTML(a.asset)}" title="Copy ${escapeHTML(a.asset)} contract on ${escapeHTML(a.network)}" aria-label="Copy ${escapeHTML(a.asset)} contract on ${escapeHTML(a.network)}"><code>${full?a.address:a.address.slice(0,8)+'…'+a.address.slice(-6)}</code>${icon('copy')}</button>`}
function settlement(){return source().direct?source():StratoFunding.get('strato-'+source().asset.toLowerCase())}
function balanceOf(a){return StratoSwap.balance(s,a)}
function debitSettlement(){const a=settlement(),qty=s.amount/a.rate;if(a.id==='strato-usdst')s.usdst-=qty;else s.sourceBalances={...(s.sourceBalances||{}),[a.id]:Math.max(0,balanceOf(a)-qty)}}
function sourcePicker(filter=fundingFilter,side=pickerSide){pickerSide=side;fundingFilter=filter;const receiving=side==='receive',assets=StratoFunding.routes.filter(a=>!receiving||a.direct);modal(heading(receiving?'Receive Token':'Pay With')+`<label class="sr-only" for="asset-search">Search tokens, networks or contracts</label><input id="asset-search" class="regular-input asset-search" placeholder="Search tokens, networks or contracts" autocomplete="off"><div class="network-filters">${(receiving?['STRATO']:['All','Ethereum','Base','Linea','Robinhood','STRATO']).map(n=>`<button data-funding-filter="${n}" class="${n===filter?'active':''}">${n}</button>`).join('')}</div><div class="funding-list">${assets.filter(a=>filter==='All'||a.network===filter).map(a=>`<div class="funding-row"><button class="funding-option" ${receiving?'data-output':'data-source'}="${a.id}">${img(a.icon,'')}<span class="funding-token-name"><strong>${a.asset}</strong><small>${a.network}</small></span><span class="funding-balance">${s.wallet?assetQuantity(balanceOf(a),a.asset):''}</span>${(receiving?output():source()).id===a.id?icon('check'):''}</button><div class="funding-contract">${contractChip(a)}</div></div>`).join('')}</div><p class="asset-no-results" hidden>No matching assets.</p>`)}
function updateSwapEstimate(){refreshAmount();const a=source();let el=$('#receive-amount');if(el)el.textContent=assetQuantity(receiveQty(),output().asset);el=$('#pay-usd');if(el)el.textContent=money(s.amount);el=$('#receive-usd');if(el)el.textContent=money(s.amount);el=$('#amount');if(el&&document.activeElement!==el)el.value=Number(sourceQty().toFixed(quantityDecimals(a.asset)))}
function quotePrice(){return s.phase>0&&s.phase<4&&s.quotePrice?s.quotePrice:PRICE}
function chart(kind='price',height=310){
 if(kind==='price')return StratoMarket.render(period,chartStyle,height);
 if(kind==='projection')return projectionChart(height);
 const series=StratoMarket.getSeries(period),final=series.at(-1).close,vals=series.map(c=>totalValue()*c.close/final),min=Math.min(...vals)*.996,max=Math.max(...vals)*1.004,span=max-min||1;
 const pts=vals.map((v,i)=>[i/(vals.length-1)*680,16+(max-v)/span*(height-36)]),path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
 return `<div class="chart portfolio-chart" data-chart="portfolio" data-values="${vals.join(',')}" style="height:${height}px"><svg viewBox="0 0 680 ${height}" preserveAspectRatio="none" role="img" aria-label="Portfolio value chart"><path class="grid" d="M0 ${height*.3}H680 M0 ${height*.7}H680"/><path d="${path}L680,${height}L0,${height}Z" fill="#3452ff" opacity=".04"/><path d="${path}" fill="none" stroke="#3452ff" stroke-width="2" vector-effect="non-scaling-stroke"/><circle class="end" cx="680" cy="${pts.at(-1)[1]}" r="4"/></svg><div class="chart-hover"><div class="chart-tooltip"></div></div></div>`
}
function projectionBase(){return Math.max(0,Number(stakeAmount)||s.staked||0)}
function projectionChart(height=210){
 const count=projectionMonths===1?15:projectionMonths===3?12:projectionMonths===6?12:12,base=projectionBase(),vals=Array.from({length:count},(_,i)=>base*(Math.pow(1+APY,projectionMonths*(i+1)/count/12)-1)),max=Math.max(...vals,.01),w=680,step=w/count,bw=Math.min(30,step*.56),bottom=height-25;
 let bars=vals.map((v,i)=>{const h=12+v/max*(height-65);return `<rect class="reward-bar" x="${i*step+(step-bw)/2}" y="${bottom-h}" width="${bw}" height="${h}" rx="4" fill="${i===count-1?'#16A673':'#BCE8D8'}" style="animation-delay:${i*24}ms"/><circle cx="${i*step+step/2}" cy="${bottom-h-5}" r="${i===count-1?4:2}" fill="#16A673"/>`}).join('');
 const path=vals.map((v,i)=>(i?'L':'M')+(i*step+step/2)+','+(bottom-(12+v/max*(height-65))-5)).join(' ');
 return `<div class="chart rewards-chart" data-chart="projection" data-values="${vals.join(',')}" style="height:${height}px"><svg viewBox="0 0 680 ${height}" preserveAspectRatio="none" role="img" aria-label="Estimated cumulative staking rewards over ${projectionMonths} months"><path class="reward-grid" d="M0 ${height*.35}H680 M0 ${height*.65}H680 M0 ${bottom}H680"/>${bars}<path d="${path}" fill="none" stroke="#16A673" stroke-width="1.5" stroke-dasharray="2 4" vector-effect="non-scaling-stroke"/></svg><div class="chart-hover"><div class="chart-tooltip"></div></div></div>`
}
function marketChange(){const m=StratoMarket.summary(period),up=m.delta>=0;return `<span class="${up?'market-up':'market-down'}">${up?'+':'−'}${money(Math.abs(m.delta))} (${num(Math.abs(m.percent))}%)</span><span class="muted">${m.label}</span>`}
function marketLabels(){return StratoMarket.labels(period).map(t=>`<span>${t}</span>`).join('')}
function about(){return `<section class="about"><h2>About STRATO</h2><p><strong>STRATO is the network token for an economy built around real assets.</strong></p><p>STRATO’s mission is to bring hard assets into digital finance, starting with gold and silver and building toward a wider world of assets. Turning them into digital tokens makes ownership easier to divide, move and use. The STRATO app and a growing ecosystem of applications let people trade, borrow and earn with that value.</p><p>The network token helps make this economy possible. Stake STRATO to help keep the network secure and running, and earn a share of validator rewards. More assets and applications create more ways to use the network. Built by early Ethereum contributors, STRATO is working toward a financial system where more people can put real-world value to work.</p><div class="about-contract"><span>STRATO contract · STRATO Mainnet</span>${contractChip(StratoFunding.output)}</div><div class="about-links"><a href="https://strato.nexus/" target="_blank" rel="noopener">${icon('globe')}Website</a><a href="https://docs.strato.nexus/tokenomics/" target="_blank" rel="noopener">${icon('external')}Token Details</a></div></section><div class="stake-inline"><div class="stake-symbol">${icon('stake')}</div><div><h3>Earn with your STRATO</h3><p>Stake your tokens. Support the network.</p></div><div class="rate">9.70%<small>Variable APY</small></div><a href="#stake">Stake</a></div>`}
function tradePage(){return `${tradeBanner()}<div class="layout"><div><div class="token-heading">${token()}<div><h1>STRATO</h1><div class="network">STRATO Network</div></div><span class="market-live"><i></i>Live</span></div><div class="price" id="chart-price">${money4(PRICE)}</div><div class="change" id="price-change">${marketChange()}</div><div id="main-chart">${chart()}</div><div class="chart-labels" id="market-time-labels">${marketLabels()}</div><div class="chart-toolbar">${periodButtons()}<div class="chart-style"><button class="icon-button ${chartStyle==='line'?'active':''}" data-style="line" aria-label="Line chart">${icon('line')}</button><button class="icon-button ${chartStyle==='candle'?'active':''}" data-style="candle" aria-label="Candlestick chart">${icon('candle')}</button></div></div>${about()}</div><aside class="order" id="order">${order()}</aside></div>`}
function money4(value){return '$'+num(value,4)}
function purchaseRoute(stage=0){return `<div class="purchase-route" aria-label="Swap route"><div class="route-stop ${stage===1?'active':''}">${sourceToken()}<strong>${source().asset}</strong><span>${source().network}</span></div><div class="route-connector ${stage>=2?'complete':''}"></div><div class="route-stop ${stage===2?'active':''}">${sourceToken()}<strong>${source().asset}</strong><span>On STRATO</span></div><div class="route-connector ${stage>=3?'complete':''}"></div><div class="route-stop ${stage===3?'active':''}">${img(output().icon,output().asset)}<strong>${output().asset}</strong><span>Your token</span></div></div>`}
function progress(n){return `<div class="mini-progress" aria-label="Step ${n} of 3">${[1,2,3].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`}
function pairVisual(){return `<div class="native-route">${sourceToken()}<span>${source().asset}</span>${icon('swap')}${img(output().icon,output().asset)}<span>${output().asset}</span></div>`}
function swapSummary(){const q=s.swapQuote;return `${dataRow('You pay',assetQuantity(q.payQty,q.fromAsset)+' '+q.fromAsset)}${dataRow('You receive','≈ '+assetQuantity(q.receiveQty,q.toAsset)+' '+q.toAsset)}${dataRow('Minimum received',assetQuantity(q.minimum,q.toAsset)+' '+q.toAsset)}${dataRow('Price tolerance',s.slippage+'%')}${dataRow('STRATO gas','Covered')}`}
function order(){
 const a=source(),to=output();
 if(s.phase===4){const q=s.lastSwap||{toAsset:'STRATO',receiveQty:s.lastBought||0};return `<div class="success"><div class="success-mark">${icon('check')}</div><h2>Swap complete.</h2><div class="received">${assetQuantity(q.receiveQty,q.toAsset)} ${q.toAsset}</div><div class="address">In your wallet on STRATO · 0x71c…4F2a</div>${q.toAsset==='STRATO'?'<button class="primary" data-action="go-stake">Stake & Earn</button>':''}<button class="${q.toAsset==='STRATO'?'secondary':'primary'}" data-action="go-portfolio">View Portfolio</button><button class="back" style="margin:20px 0 0" data-action="buy-more">Make Another Swap</button></div>`}
 if(s.phase===0)return `<div class="swap-title"><h2>Swap</h2><button class="icon-button" data-action="trade-settings" aria-label="Swap settings">${icon('settings')}</button></div><div class="swap-input-panel"><div class="swap-panel-label"><label for="amount">You pay</label><div class="swap-percentages">${[25,50,75,100].map(v=>`<button data-funding-percent="${v}">${v===100?'Max':v+'%'}</button>`).join('')}</div></div><div class="swap-amount-row"><input id="amount" aria-label="Amount of ${a.asset} to pay" type="number" inputmode="decimal" min="0" step="any" value="${Number(sourceQty().toFixed(quantityDecimals(a.asset)))}"><button class="swap-asset-picker" data-action="choose-source">${sourceToken()}<strong>${a.asset}</strong>${icon('down')}</button></div><div class="swap-value-row"><span id="pay-usd">${money(s.amount)}</span><button data-action="choose-source">${a.network}${s.wallet?' · '+assetQuantity(sourceBalance())+' '+a.asset:''}</button></div><div class="swap-contract">${contractChip(a)}</div></div><button class="swap-divider reverse-swap" data-action="reverse-pair" aria-label="Reverse swap direction" title="Reverse swap direction">${icon('swap')}</button><div class="swap-output-panel"><label>You receive</label><div class="swap-amount-row"><span id="receive-amount">${assetQuantity(receiveQty(),to.asset)}</span><button class="swap-asset-picker output-token" data-action="choose-output">${img(to.icon,to.asset)}<strong>${to.asset}</strong>${icon('down')}</button></div><div class="swap-value-row"><span id="receive-usd">${money(s.amount)}</span><span>STRATO Network</span></div><div class="swap-contract">${contractChip(to)}</div></div><div id="order-error" class="error" hidden></div><button class="primary swap-review" data-action="begin">${s.wallet?'Review Swap':'Connect Wallet'}</button><div class="swap-route-note">${a.direct?`${icon('swap')}Swap ${a.asset} for ${to.asset} on STRATO.`:`${icon('globe')}Bridge ${a.asset} from ${a.network}, then swap for ${to.asset} on STRATO.`}</div><div class="gas">${icon('gas')}STRATO gas paid by us</div>`;
 if(s.phase===1)return `${progress(1)}<button class="back" data-action="edit-amount">Back</button><h2>Review your swap</h2><p class="description">${a.direct?`Exchange ${a.asset} for ${to.asset} in one swap. Your ${to.asset} stays in your wallet on STRATO.`:`First, bridge ${a.asset} from ${a.network}. Receive it on STRATO, then swap it for ${to.asset}.`}</p>${a.direct?pairVisual():purchaseRoute(1)}${swapSummary()}${dataRow('Bridge fee',a.direct?'None':'≈ $0.02 in ETH')}<button class="primary" data-action="fund">${a.direct?'Continue to Swap':'Continue to Bridge'}</button>`;
 if(s.phase===2){const permission=!a.native;return `${progress(2)}<h2>Bridge to STRATO</h2><p class="description">Receive ${assetQuantity(sourceQty())} ${a.asset} on STRATO, ready to swap for ${to.asset}.</p>${purchaseRoute(2)}<div class="step-list">${permission?`<div class="step-row ${hasAllowance()?'done':'current'}"><span class="step-dot">${hasAllowance()?icon('check'):'1'}</span><div><strong>Allow ${assetQuantity(sourceQty())} ${a.asset}</strong><p>Permission for the amount you chose.</p></div></div>`:''}<div class="step-row current"><span class="step-dot">${permission?'2':'1'}</span><div><strong>Bridge ${a.asset} to STRATO</strong><p>Send from ${a.network}. Receive on STRATO.</p></div></div><div class="step-row"><span class="step-dot">${permission?'3':'2'}</span><div><strong>Next: swap for ${to.asset}</strong><p>Confirm one swap when your funds arrive.</p></div></div></div><button class="primary" data-action="resume-fund">${a.native||hasAllowance()?'Confirm Bridge':'Allow '+a.asset}</button>`}
 return `${progress(3)}<button class="back" data-action="back-to-swap">Back to Swap</button><h2>Swap for ${to.asset}</h2><p class="description">${a.direct?`Your ${a.asset} is ready.`:`Your ${assetQuantity(sourceQty())} ${a.asset} has arrived on STRATO.`} Confirm one swap to receive ${to.asset}.</p>${pairVisual()}${swapSummary()}${dataRow('Receiving network','STRATO')}<button class="primary" data-action="confirm-swap">Review Wallet Request</button>`
}
function emptyView(title,desc){return `<div class="empty">${icon('wallet')}<h2>${title}</h2><p>${desc}</p><button class="primary" data-action="wallet">Connect Wallet</button></div>`}
function walletCaption(){return s.wallet?`<span class="wallet-caption">${img(walletAsset(),'')}0x71c…4F2a</span>`:''}
function otherNativeValue(){return StratoFunding.routes.filter(a=>a.direct&&!['STRATO','USDST'].includes(a.asset)).reduce((v,a)=>v+balanceOf(a)*a.rate,0)}
function totalValue(){return (s.available+s.staked+rewards())*PRICE+s.usdst+s.lp+otherNativeValue()}
function otherAssetRows(){return StratoFunding.routes.filter(a=>a.direct&&!['STRATO','USDST'].includes(a.asset)&&balanceOf(a)>0).map(a=>`<tr><td><div class="asset-cell">${img(a.icon,a.asset)}<div><b>${a.asset}</b><span>STRATO Network</span></div></div></td><td>${assetQuantity(balanceOf(a),a.asset)}</td><td>${money(balanceOf(a)*a.rate)}</td><td><button class="text-button" data-trade-source="${a.id}">Swap</button></td></tr>`).join('')}
function historyTable(limit=7,types=null){const rows=types?s.history.filter(a=>types.includes(a.type)):s.history;return rows.length?`<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Amount</th><th>Status</th><th>Time</th></tr></thead><tbody>${rows.slice(0,limit).map(a=>`<tr><td><div class="asset-cell"><div class="activity-icon">${icon(['Buy','Claim','Bridge'].includes(a.type)?'receive':a.type==='Stake'?'stake':'send')}</div><b>${a.type}</b></div></td><td>${num(a.amount)} ${a.asset}</td><td><span class="pill">Completed</span></td><td class="muted">${new Date(a.time).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</td></tr>`).join('')}</tbody></table></div>`:'<div class="position-empty">Your transactions will appear here.</div>'}
function portfolioPage(){let total=totalValue();return `<div class="page-header"><h1>Portfolio</h1>${walletCaption()}</div>${!s.wallet?emptyView('Your assets, in one place.','Connect your wallet to see your STRATO and staking positions.'):`<div class="page-layout"><div><div class="balance-heading">Total portfolio value</div><div class="balance">${money(total)}</div><div class="change">${money(rewards()*PRICE)}<span class="muted">staking rewards</span></div>${chart('portfolio',240)}<div class="chart-toolbar">${periodButtons(['1D','1W','1M','ALL'])}<span class="small muted">USD</span></div><section class="section"><h2 class="section-title">Your Assets</h2><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Balance</th><th>Value</th><th></th></tr></thead><tbody><tr><td><div class="asset-cell">${token()}<div><b>STRATO</b><span>Available</span></div></div></td><td>${num(s.available)}</td><td>${money(s.available*PRICE)}</td><td><button class="text-button" data-trade-source="strato-strato">Swap</button></td></tr><tr><td><div class="asset-cell">${token()}<div><b>Staked STRATO</b><span>Validator 01</span></div></div></td><td>${num(s.staked)}</td><td>${money(s.staked*PRICE)}</td><td><button class="text-button" data-action="go-stake">Manage</button></td></tr><tr><td><div class="asset-cell">${stable()}<div><b>USDST</b><span>STRATO Network</span></div></div></td><td>${num(s.usdst)}</td><td>${money(s.usdst)}</td><td><button class="text-button" data-action="bridge-tab">Bridge</button></td></tr>${otherAssetRows()}${s.lp?`<tr><td><div class="asset-cell">${icon('swap')}<div><b>STRATO / USDST</b><span>Liquidity position</span></div></div></td><td>Pool shares</td><td>${money(s.lp)}</td><td><a class="text-button" href="#advanced">Manage</a></td></tr>`:''}</tbody></table></div></section><section class="section"><h2 class="section-title">Activity</h2>${historyTable()}</section></div><aside><div class="info-card"><h3>Allocation</h3><div class="allocation"><span style="width:${total?s.available*PRICE/total*100:0}%"></span><span style="width:${total?(s.staked+rewards())*PRICE/total*100:0}%"></span><span style="width:${total?s.usdst/total*100:0}%"></span><span style="width:${total?otherNativeValue()/total*100:0}%;background:#7c9cc8"></span>${s.lp?`<span style="width:${s.lp/total*100}%;background:#a2b2e5"></span>`:''}</div><div class="allocation-label"><span><i></i>STRATO</span><span>${num(total?s.available*PRICE/total*100:0,1)}%</span></div><div class="allocation-label"><span><i></i>Stake & rewards</span><span>${num(total?(s.staked+rewards())*PRICE/total*100:0,1)}%</span></div><div class="allocation-label"><span><i></i>USDST</span><span>${num(total?s.usdst/total*100:0,1)}%</span></div><div class="allocation-label"><span><i style="background:#7c9cc8"></i>Other assets</span><span>${num(total?otherNativeValue()/total*100:0,1)}%</span></div>${s.lp?`<div class="allocation-label"><span><i style="background:#a2b2e5"></i>Liquidity</span><span>${num(s.lp/total*100,1)}%</span></div>`:''}</div><div class="info-card"><h3>Your STRATO can earn.</h3><p>Stake your available tokens and earn variable rewards.</p><div class="balance" style="font-size:36px">9.70% <span class="muted small">APY</span></div><button class="primary" data-action="go-stake" style="margin-top:22px">Stake STRATO</button></div></aside></div>`}`}
function stakingPage(){return `<div class="stake-head"><h1>Staking</h1><div class="stake-apr">Current APY<strong>9.70%</strong></div></div><div class="page-layout"><div><div class="reward-stage"><div class="reward-emblem">${token()}<i></i><i></i></div><div class="reward-label">${s.staked?'<span class="live-orb"></span>':''}Your staking rewards</div><div class="reward-total"><span id="live-rewards">${num(rewards(),6)}</span> <small>STRATO</small></div><div class="small muted" id="reward-dollars">≈ ${money(rewards()*PRICE)}</div><div class="reward-tools"><button class="secondary" data-action="claim" ${!s.wallet||rewards()<=0?'disabled':''}>Claim Rewards</button><button class="secondary" data-action="restake" ${!s.wallet||rewards()<=0?'disabled':''}>Restake</button></div></div><div class="metrics"><div><label>Total staked</label><strong>${num(s.staked)} <small>STRATO</small></strong></div><div><label>Est. monthly rewards</label><strong>${num(s.staked*(Math.pow(1+APY,1/12)-1))} <small>STRATO / month</small></strong></div><div><label>Unstaking period</label><strong>7 days<small>Until tokens are available</small></strong></div></div><div class="projection"><h3>Your earning potential</h3><div class="projection-total" id="projection-total">+${num(projectionBase()*(Math.pow(1+APY,projectionMonths/12)-1))} STRATO</div><p id="projection-caption">On ${num(projectionBase(),0)} STRATO over ${projectionMonths===12?'1 year':projectionMonths+' months'} · variable APY.</p><div id="projection-chart">${chart('projection',210)}</div><div class="chart-labels"><span>Today</span><span>${projectionMonths===12?'1 year':projectionMonths+' months'}</span></div><div class="periods">${[1,3,6,12].map(m=>`<button data-months="${m}" class="${m===projectionMonths?'active':''}">${m===12?'1Y':m+'M'}</button>`).join('')}</div></div><section class="section"><div class="section-heading-row"><h2 class="section-title">Your Positions</h2></div>${s.staked?`<div class="table-wrap"><table><thead><tr><th>Validator</th><th>Staked</th><th>APY</th><th>Status</th></tr></thead><tbody><tr><td><div class="asset-cell">${token()}<div><b>STRATO Validator 01</b><span>Commission included in APY</span></div></div></td><td>${num(s.staked)}</td><td>9.70%</td><td><span class="pill">Earning</span></td></tr></tbody></table></div>`:'<div class="position-empty">Stake STRATO to start your first position.</div>'}${s.unbond.length?`<h3 style="font-size:16px;font-weight:500;margin-top:28px">Unstaking</h3>${s.unbond.map(u=>dataRow(num(u.amount)+' STRATO','Available '+new Date(u.release).toLocaleDateString('en-GB',{day:'numeric',month:'short'}))).join('')}`:''}</section><div class="chart-caption">APY is variable. Estimates assume the current rate continues and are not guaranteed.</div></div><aside class="order" id="stake-order">${stakeOrder()}</aside></div>`}
function stakeOrder(){let unstake=stakeMode==='unstake';return `<div class="order-tabs"><button data-stake-mode="stake" class="${!unstake?'active':''}">Stake</button><button data-stake-mode="unstake" class="${unstake?'active':''}">Unstake</button></div><label class="field-label" for="stake-amount">${unstake?'Amount to unstake':'Amount to stake'}</label><div class="stake-input">${token()}<input id="stake-amount" type="number" inputmode="decimal" min="0" step="any" value="${stakeAmount}"><span>STRATO</span></div><input class="range" id="stake-range" aria-label="Percentage of available STRATO" type="range" min="0" max="100" value="${Math.min(100,stakeAmount/Math.max(1,unstake?s.staked:s.available)*100)}"><div class="data-row" style="margin-top:4px"><span>Available</span><button class="text-button" data-action="stake-max">${num(unstake?s.staked:s.available)} STRATO</button></div>${!unstake?`<button class="validator" data-action="validator" style="width:100%;text-align:left">${icon('shield')}<span>STRATO Validator 01</span>${icon('down')}</button><div class="order-summary">${dataRow('Estimated yearly rewards',`<span id="stake-estimate">${num(stakeAmount*APY)}</span> STRATO`)}${dataRow('APY','9.70% · variable')}${dataRow('Network fee','Covered')}</div>`:`<div class="order-summary">${dataRow('Unstaking period','7 days')}${dataRow('Available on',new Date(Date.now()+7*86400000).toLocaleDateString('en-GB',{day:'numeric',month:'long'}))}</div>`}<div id="stake-error" class="error" hidden></div><button class="primary" data-action="review-stake">${s.wallet?(unstake?'Unstake STRATO':'Stake STRATO'):'Connect Wallet'}</button><p class="unbond">${unstake?'Rewards stop on the amount you unstake.':'Unstake anytime. Tokens available after 7 days.'}</p>`}
function advancedPage(){return `<div class="page-header"><h1>Advanced</h1>${walletCaption()}</div><div class="tabs" role="tablist" aria-label="Advanced tools">${['pools','bridge','activity','settings'].map(t=>`<button role="tab" aria-selected="${advancedTab===t}" data-tab="${t}" class="${advancedTab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${advancedTab==='pools'?pools():advancedTab==='bridge'?bridgePage():advancedTab==='activity'?`<section><div class="activity-heading"><h2 class="section-title">Transaction History</h2><button data-action="export-activity">Export CSV</button></div>${historyTable(30)}</section>`:settings()}`}
function pools(){return `<div class="page-layout"><div><div class="pool-banner"><div class="pool-title"><div class="paired">${token()}${stable()}</div><div><h2>STRATO / USDST</h2><span class="small muted">0.3% fee tier</span></div></div><div class="pool-rate">12.01%<span>Variable pool APY</span></div></div><h2 class="section-title">Pool Overview</h2><div class="pool-metrics"><div><label>Your liquidity</label><strong>${money(s.lp)}</strong></div><div><label>Est. monthly rewards</label><strong>${money(s.lp*POOLAPY/12)}</strong></div><div><label>Pair</label><strong>50 / 50</strong></div></div><section class="section"><h2 class="section-title">Your Position</h2>${s.lp?`<div class="position-detail">${dataRow('Position value',money(s.lp))}${dataRow('STRATO supplied',num(s.lp/2/PRICE))}${dataRow('USDST supplied',num(s.lp/2))}<button class="secondary" data-action="remove-lp" style="margin-top:16px">Remove Liquidity</button></div>`:'<div class="position-empty">No liquidity position yet.</div>'}</section><section class="section"><h2 class="section-title">Before You Add Liquidity</h2><p class="muted" style="font-size:15px;line-height:1.7">Supply equal values of STRATO and USDST. You earn a share of trading fees and eligible rewards. Your token amounts change as the pool price moves, and you may receive less than if you had simply held the tokens.</p></section></div><aside class="order"><h2>Add Liquidity</h2><p class="description">STRATO / USDST</p><label class="field-label" for="lp-amount">Total deposit value</label><div class="pay-field"><div class="money-input"><span>$</span><input id="lp-amount" type="number" inputmode="decimal" min="0" value="250"><span class="currency">USD</span></div></div><div id="lp-summary">${dataRow('STRATO',num(125/PRICE))}${dataRow('USDST','125.00')}</div>${dataRow('Network fee','Covered')}<div id="lp-error" class="error" hidden></div><button class="primary" data-action="add-lp">${s.wallet?'Review Deposit':'Connect Wallet'}</button></aside></div>`}
function bridgePage(){return `<div class="page-layout"><div><h2 class="section-title">Bring Funds to STRATO</h2><p class="muted" style="font-size:15px;max-width:500px;line-height:1.7">Transfer USDC from your wallet. Receive USDC on STRATO, ready to trade.</p><div class="step-list" style="margin-top:36px"><div class="step-row"><span class="step-dot">1</span><div><strong>Choose your network and amount</strong><p>USDC from Base or Ethereum.</p></div></div><div class="step-row"><span class="step-dot">2</span><div><strong>Allow and confirm in your wallet</strong><p>Your source network may charge a fee.</p></div></div><div class="step-row"><span class="step-dot">3</span><div><strong>Receive USDC on STRATO</strong><p>Keep it in your portfolio or buy STRATO.</p></div></div></div><section class="section"><h2 class="section-title">Bridge Activity</h2>${historyTable(5,['Bridge'])}</section></div><aside class="order"><h2>Bridge</h2><p class="description">USDC to STRATO</p><label class="field-label" for="bridge-network">From</label><select class="regular-input" id="bridge-network"><option>Base</option><option>Ethereum</option><option>Linea</option></select><label class="field-label" style="margin-top:20px" for="bridge-amount">Amount in USDC</label><div class="pay-field"><div class="money-input"><input id="bridge-amount" type="number" min="1" max="10000" value="250"><span class="currency">USDC</span></div></div><div class="route-visual">${usdc()}<div class="route-line"></div>${stable()}</div>${dataRow('Destination','STRATO')}${dataRow('Transfer fee','≈ $0.02 in test ETH')}<p class="error" id="bridge-error" hidden>Enter an amount between 1 and 10,000 USDC.</p><button class="primary" data-action="standalone-bridge">${s.wallet?'Review Transfer':'Connect Wallet'}</button></aside></div>`}
function settings(){return `<div style="max-width:740px"><div class="settings-row"><div><h3>Price Tolerance</h3><p>Maximum price movement accepted for a trade.</p></div><div class="chips">${[.1,.5,1].map(v=>`<button data-slippage="${v}" class="${s.slippage===v?'active':''}">${v}%</button>`).join('')}</div></div><div class="settings-row"><div><h3>Connected Wallet</h3><p>${s.wallet?s.wallet+' · 0x71c…4F2a':'No wallet connected'}</p></div><button class="text-button" data-action="${s.wallet?'disconnect':'wallet'}">${s.wallet?'Disconnect':'Connect'}</button></div><div class="settings-row"><div><h3>Session</h3><p>Clear balances, positions and transaction history.</p></div><button class="text-button" data-action="reset">Reset</button></div></div>`}
function render(){hoveringPrice=false;if(!['trade','portfolio','stake','advanced'].includes(page))page='trade';persist();document.body.classList.toggle('landing-view',page==='home');$('.brand').href=variant==='landing'?'#home':'#trade';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+page);if(a.hash==='#'+page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title='STRATO — '+({home:'The Hard-Asset Economy',trade:'Trade',portfolio:'Portfolio',stake:'Staking',advanced:'Advanced'}[page]);$('#app').innerHTML=`<div class="view-in">${page==='trade'?tradePage():page==='portfolio'?portfolioPage():page==='stake'?stakingPage():advancedPage()}</div>`;}
function connect(next){if(s.wallet){next?.();return}connectionNext=next;modal(heading('Connect Wallet')+`<p class="modal-sub">Choose your wallet.</p>${[['MetaMask','metamask.svg'],['WalletConnect','walletconnect.svg'],['STRATO Wallet','token-strato.png']].map(([name,asset])=>`<button class="wallet-option" data-wallet="${name}">${img(asset,'')}<span class="option-info">${name}</span>${icon('chevron')}</button>`).join('')}`)}
async function chooseWallet(name){busy=true;const asset=name==='MetaMask'?'metamask.svg':name==='WalletConnect'?'walletconnect.svg':'token-strato.png';modal(heading('Connecting')+`<div class="wallet-connection"><div class="wallet-art">${img(asset,name)}<i class="orbit"></i></div><h3>Connecting to ${name}</h3><p>Waiting for your wallet…</p></div>`);await delay(1800);s.wallet=name;if(!s.seeded){s.available=1250;s.staked=2500;s.usdst=500;s.rewards=12.482631;s.rewardStart=Date.now();s.seeded=true;s.history=[{type:'Stake',amount:2500,asset:'STRATO',time:Date.now()-3*86400000,id:'seed01'},{type:'Buy',amount:3750,asset:'STRATO',time:Date.now()-3*86400000-300000,id:'seed02'}]}busy=false;persist();closeModal();render();toast('Wallet connected');if(connectionNext){let next=connectionNext;connectionNext=null;next()}}
const delay=t=>new Promise(r=>setTimeout(r,t));
function walletMenu(){if(!s.wallet){connect();return}modal(heading('Your Wallet')+`<div class="wallet-connection"><div class="wallet-art">${img(walletAsset(),s.wallet)}</div><h3>${s.wallet}</h3><p>0x71c…4F2a</p></div><div class="modal-actions"><button class="primary" data-action="go-portfolio">View Portfolio</button><button class="secondary" data-action="disconnect">Disconnect</button></div>`)}
function chooseNetwork(){modal(heading('Pay From')+`<p class="modal-sub">Select where your funds are.</p>${['Base','Ethereum','STRATO'].map(n=>`<button class="network-option" data-network="${n}">${n==='STRATO'?stable():usdc()}<div><strong>${n==='STRATO'?'USDST on STRATO':'USDC on '+n}</strong><small>${n==='STRATO'?money(s.usdst)+' available':'10,000 USDC available'}</small></div>${s.network===n?icon('check'):''}</button>`).join('')}`)}
let tx={};
function request(type,payload={}){if(!s.wallet){connect(()=>request(type,payload));return}tx={type,quote:type==='swap'?{...s.swapQuote}:null,price:type==='buy'?quotePrice():PRICE,...payload};let info={swap:{title:'Swap '+settlement().asset+' for '+output().asset,amount:assetQuantity(s.swapQuote?.receiveQty,output().asset)+' '+output().asset,asset:output().icon,desc:'Exchange '+assetQuantity(s.swapQuote?.payQty,source().asset)+' '+source().asset+' for approximately '+assetQuantity(s.swapQuote?.receiveQty,output().asset)+' '+output().asset+'. Your '+output().asset+' will be received on STRATO.',network:'STRATO',fee:'Covered by STRATO',button:'Confirm Swap'},allow:{title:'Allow '+source().asset,amount:assetQuantity(sourceQty())+' '+source().asset,asset:source().icon,desc:'Allow the bridge to use only '+assetQuantity(sourceQty())+' '+source().asset+'. Your funds move when you confirm the bridge.',network:source().network,fee:'≈ $0.01 in ETH',button:'Allow '+source().asset},bridge:{title:'Bridge '+source().asset+' to STRATO',amount:assetQuantity(sourceQty())+' '+source().asset,asset:source().icon,desc:'Send from '+source().network+' and receive approximately '+assetQuantity(sourceQty())+' '+source().asset+' on STRATO. One swap receives '+output().asset+' after your funds arrive.',network:source().network,fee:'≈ $0.02 in ETH',button:'Confirm Bridge'},buy:{title:'Buy STRATO',amount:num(s.amount/quotePrice())+' STRATO',asset:'token-strato.png',desc:'Exchange your '+(assetQuantity(sourceQty())+' '+source().asset)+' for '+num(s.amount/quotePrice())+' STRATO tokens. This is the token purchase.',network:'STRATO',fee:'Covered by STRATO',button:'Confirm Purchase'},sell:{title:'Sell STRATO',amount:num(s.amount)+' STRATO',asset:'token-strato.png',desc:'Receive approximately '+num(s.amount*tx.price)+' USDST in your wallet.',network:'STRATO',fee:'Covered',button:'Confirm Sale'},stake:{title:'Stake STRATO',amount:num(stakeAmount)+' STRATO',asset:'token-strato.png',desc:'Delegate to STRATO Validator 01. You earn variable rewards. Unstaking takes 7 days.',network:'STRATO',fee:'Covered',button:'Confirm Stake'},unstake:{title:'Unstake STRATO',amount:num(stakeAmount)+' STRATO',asset:'token-strato.png',desc:'Your tokens will be available after 7 days. Rewards stop on this amount.',network:'STRATO',fee:'Covered',button:'Confirm Unstake'},claim:{title:'Claim Rewards',amount:num(rewards(),6)+' STRATO',asset:'token-strato.png',desc:'Move your staking rewards into your available STRATO balance.',network:'STRATO',fee:'Covered',button:'Claim Rewards'},restake:{title:'Restake Rewards',amount:num(rewards(),6)+' STRATO',asset:'token-strato.png',desc:'Add your rewards to your active stake to earn on a larger position.',network:'STRATO',fee:'Covered',button:'Confirm Restake'},lp:{title:'Add Liquidity',amount:money(payload.amount),asset:'token-strato.png',desc:'Supply '+num(payload.amount/2/PRICE)+' STRATO and '+num(payload.amount/2)+' USDST to the pool.',network:'STRATO',fee:'Covered',button:'Confirm Deposit'},remove:{title:'Remove Liquidity',amount:money(s.lp),asset:'token-usdst.png',desc:'Withdraw your STRATO and USDST from the pool into your wallet.',network:'STRATO',fee:'Covered',button:'Confirm Withdrawal'}}[type];modal(heading(info.title)+`<p class="modal-sub">${info.desc}</p><div class="approval-amount">${img(info.asset,'')}${info.amount}</div><div class="position-detail">${dataRow('Network',info.network)}${dataRow('Wallet','0x71c…4F2a')}${dataRow('Network fee',info.fee)}</div><div class="modal-actions"><button class="primary" data-action="sign">${info.button}</button><button class="secondary" data-action="cancel-sign">Cancel</button></div><div class="wallet-provider">${img(walletAsset(),'')}Confirm in ${s.wallet}</div>`)}
async function perform(){if(busy)return;busy=true;let {type}=tx;const id=++operation;let title={allow:'Approving '+source().asset,bridge:'Bringing funds to STRATO',swap:'Swapping '+source().asset+' for '+output().asset,buy:'Buying your STRATO',sell:'Completing your sale',stake:'Activating your stake',unstake:'Unstaking your STRATO',claim:'Claiming rewards',restake:'Restaking your rewards',lp:'Adding your liquidity',remove:'Removing your liquidity'}[type];modal(heading(title)+`<div class="transaction-view"><div class="transaction-visual">${img(['allow','bridge','swap'].includes(type)?source().icon:'token-strato.png','')}<span class="transaction-track"></span>${img(type==='swap'?output().icon:type==='bridge'?source().icon:['sell','remove'].includes(type)?'token-usdst.png':'token-strato.png','')}</div><h3>${type==='bridge'?'Transfer in progress':'Confirming on the network'}</h3><p>${type==='bridge'?'Your '+source().asset+' will arrive on STRATO.':'Your wallet request has been received.'}</p><div class="processing-bar"><i></i></div></div>`);await delay(type==='bridge'?3000:2400);if(operation!==id)return;busy=false;
if(type==='allow'){s.allowance=s.amount;s.allowanceSource=source().id;persist();render();request('bridge',{standalone:tx.standalone});return}
if(type==='bridge'){s.sourceBalances={...(s.sourceBalances||{}),[source().id]:Math.max(0,sourceBalance()-sourceQty())};const dest=settlement(),qty=sourceQty();if(dest.id==='strato-usdst')s.usdst+=qty;else s.sourceBalances={...(s.sourceBalances||{}),[dest.id]:balanceOf(dest)+qty};s.bridged=s.amount;recordActivity('Bridge',qty,source().asset);if(tx.standalone){s.phase=0;closeModal();render();toast(source().asset+' arrived in your wallet');return}s.phase=3;persist();closeModal();render();toast('Your funds are ready');return}
if(type==='swap'){try{s=StratoSwap.apply(s,tx.quote,StratoFunding.routes)}catch(error){closeModal();render();toast(error.message);return}s.lastSwap=tx.quote;s.lastBought=tx.quote.toAsset==='STRATO'?tx.quote.receiveQty:0;s.phase=4;s.allowance=0;s.bridged=0;recordActivity(tx.quote.fromAsset==='STRATO'?'Sell':tx.quote.toAsset==='STRATO'?'Buy':'Swap',tx.quote.receiveQty,tx.quote.toAsset);closeModal();render();actionEffect('Swap complete');return}
if(type==='buy'){s.available+=s.amount/quotePrice();debitSettlement();s.lastBought=s.amount/quotePrice();s.phase=4;s.allowance=0;s.bridged=0;recordActivity('Buy',s.lastBought);closeModal();render();actionEffect('Purchase complete');return}
if(type==='sell'){s.available-=s.amount;s.usdst+=s.amount*tx.price;recordActivity('Sell',s.amount);closeModal();render();toast('Sale completed');return}
if(type==='stake'){settleRewards();s.available-=stakeAmount;s.staked+=stakeAmount;recordActivity('Stake',stakeAmount);closeModal();render();actionEffect('+'+num(stakeAmount)+' STRATO staked');toast('Your STRATO is now earning');return}
if(type==='unstake'){settleRewards();s.staked-=stakeAmount;s.unbond.push({amount:stakeAmount,release:Date.now()+7*86400000});recordActivity('Unstake',stakeAmount);closeModal();render();toast('Unstaking started · available in 7 days');return}
if(type==='claim'||type==='restake'){settleRewards();let amount=s.rewards;s.rewards=0;if(type==='claim')s.available+=amount;else s.staked+=amount;recordActivity(type==='claim'?'Claim':'Restake',amount);closeModal();render();actionEffect('+'+num(amount,4)+' STRATO '+(type==='claim'?'claimed':'restaked'));toast(type==='claim'?'Rewards added to your wallet':'Rewards added to your stake');return}
if(type==='lp'){let amount=tx.amount;s.available-=amount/2/PRICE;s.usdst-=amount/2;s.lp+=amount;recordActivity('Add liquidity',amount,'USD');closeModal();render();toast('Liquidity position created');return}
if(type==='remove'){let amount=s.lp;s.available+=amount/2/PRICE;s.usdst+=amount/2;s.lp=0;recordActivity('Remove liquidity',amount,'USD');closeModal();render();toast('Liquidity returned to your wallet')}}
function orderError(t){$('#order-error').textContent=t;$('#order-error').hidden=false}
function begin(){refreshAmount();if(!s.wallet){connect(begin);return}if(!Number.isFinite(s.amount)||s.amount<=0){orderError('Enter an amount to swap.');return}if(sourceQty()>sourceBalance()+.000000001){orderError('This amount exceeds your available '+source().asset+'.');return}if(source().asset===output().asset){orderError('Choose two different assets.');return}s.network=source().network;s.quotePrice=PRICE;try{s.swapQuote=StratoSwap.quote(settlement(),output(),sourceQty(),PRICE,s.slippage)}catch(error){orderError(error.message);return}s.phase=1;persist();render()}
function fund(){if(!s.wallet){connect(fund);return}if(source().direct){if(sourceBalance()+1e-9<sourceQty()){toast('Not enough '+source().asset+'. Choose another asset.');return}s.phase=3;persist();render();request('swap')}else{s.phase=2;persist();render();request(source().native||hasAllowance()?'bridge':'allow')}}
function updateStakeCalc(){
 let el=$('#stake-estimate');if(el)el.textContent=num(stakeAmount*APY);
 let total=$('#projection-total');if(total)total.textContent='+'+num(projectionBase()*(Math.pow(1+APY,projectionMonths/12)-1))+' STRATO';
 let caption=$('#projection-caption');if(caption)caption.textContent='On '+num(projectionBase(),0)+' STRATO over '+(projectionMonths===12?'1 year':projectionMonths+' months')+' · variable APY.';
 let c=$('#projection-chart');if(c)c.innerHTML=projectionChart(210)
}
function actionEffect(label){
 const target=$('.reward-stage')||$('.success')||$('.order');if(!target)return;
 target.classList.remove('action-glow');void target.offsetWidth;target.classList.add('action-glow');
 const float=document.createElement('div');float.className='action-receipt';float.innerHTML=icon('check')+escapeHTML(label);target.appendChild(float);setTimeout(()=>{float.remove();target.classList.remove('action-glow')},2600)
}
function settingsModal(){modal(heading('Trade Settings')+`<p class="modal-sub">Maximum price movement accepted for your purchase.</p><div class="chips">${[.1,.5,1].map(v=>`<button data-slippage="${v}" class="${s.slippage===v?'active':''}">${v}%</button>`).join('')}</div>`)}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'trade';render();window.scrollTo({top:0,behavior:'instant'})});
$('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
document.addEventListener('input',e=>{if(e.target.id==='amount'){s.payQuantity=Number(e.target.value);refreshAmount();persist();updateSwapEstimate()}if(e.target.id==='asset-search'){const q=e.target.value.toLowerCase();let count=0;document.querySelectorAll('.funding-row').forEach(b=>{b.hidden=!b.textContent.toLowerCase().includes(q);if(!b.hidden)count++});const empty=$('.asset-no-results');if(empty)empty.hidden=count>0}if(e.target.id==='stake-amount'){stakeAmount=Number(e.target.value);$('#stake-range').value=stakeAmount/Math.max(1,stakeMode==='unstake'?s.staked:s.available)*100;updateStakeCalc()}if(e.target.id==='stake-range'){stakeAmount=Math.floor((stakeMode==='unstake'?s.staked:s.available)*Number(e.target.value))/100;$('#stake-amount').value=stakeAmount;updateStakeCalc()}if(e.target.id==='lp-amount'){const v=Number(e.target.value);$('#lp-summary').innerHTML=dataRow('STRATO',num(v/2/PRICE))+dataRow('USDST',num(v/2))}});
document.addEventListener('pointermove',e=>{const c=e.target.closest('[data-chart]');if(!c)return;const r=c.getBoundingClientRect(),plot=c.dataset.chart==='price'?r.width*Number(c.dataset.plotRatio||.9):r.width,t=Math.max(0,Math.min(1,(e.clientX-r.left)/plot)),vals=c.dataset.values.split(',').map(Number),i=Math.min(vals.length-1,Math.floor(t*vals.length)),line=c.querySelector('.chart-hover'),tip=c.querySelector('.chart-tooltip');line.style.display='block';line.style.left=t*(plot/r.width)*100+'%';tip.style.left=t>.65?'-165px':'8px';
 if(c.dataset.chart==='price'){hoveringPrice=true;const row=StratoMarket.getSeries(period)[i];$('#chart-price').textContent=money4(row.close);tip.innerHTML=`<strong>${new Date(row.time).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</strong><span>O ${num(row.open,4)} &nbsp; C ${num(row.close,4)}</span><span>H ${num(row.high,4)} &nbsp; L ${num(row.low,4)}</span>`}
 else tip.textContent=c.dataset.chart==='projection'?'+'+num(vals[i])+' STRATO':money(vals[i])
});
document.addEventListener('pointerout',e=>{const c=e.target.closest('[data-chart]');if(c&&!c.contains(e.relatedTarget)){c.querySelector('.chart-hover').style.display='none';if(c.dataset.chart==='price'){hoveringPrice=false;$('#chart-price').textContent=money4(PRICE)}}});
document.addEventListener('click',e=>{if(e.target.closest('[data-start-buy]')){s.phase=0;s.amount=250;persist()}const b=e.target.closest('button');if(!b||b.disabled||busy)return;
if(b.dataset.copyAddress){const value=b.dataset.copyAddress,focus=document.activeElement,input=document.createElement('textarea');input.value=value;input.readOnly=true;input.style.cssText='position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;';($('#modal').open?$('#modal-body'):document.body).append(input);input.focus();input.select();input.setSelectionRange(0,value.length);let copied=false;try{copied=document.execCommand('copy')}catch{}input.remove();focus?.focus?.();const success=()=>toast((b.dataset.copyToken||'Token')+' contract copied');if(copied)success();else if(navigator.clipboard)navigator.clipboard.writeText(value).then(success).catch(()=>modal(heading('Copy Contract')+'<p class="modal-sub">Select and copy this address.</p><input class="regular-input" readonly value="'+value+'">'));else modal(heading('Copy Contract')+'<input class="regular-input" readonly value="'+value+'">');return}if(b.dataset.tradeSource){changePair(b.dataset.tradeSource,b.dataset.tradeSource==='strato-strato'?'strato-usdc':'strato-strato',250/StratoSwap.rate(StratoFunding.get(b.dataset.tradeSource),PRICE));go('trade');return}if(b.dataset.output){const next=StratoFunding.get(b.dataset.output);if(next.asset===source().asset){reversePair();return}s.outputId=next.id;s.phase=0;s.swapQuote=null;persist();closeModal();render();return}if(b.dataset.source){const next=StratoFunding.get(b.dataset.source),previous=settlement();const target=next.asset===output().asset?previous.id:output().id;changePair(next.id,target,s.amount/StratoSwap.rate(next,PRICE));return}if(b.dataset.fundingFilter){sourcePicker(b.dataset.fundingFilter);return}if(b.dataset.fundingPercent){s.payQuantity=sourceBalance()*Number(b.dataset.fundingPercent)/100;refreshAmount();persist();$('#order').innerHTML=order();return}if(b.dataset.wallet){chooseWallet(b.dataset.wallet);return}if(b.dataset.network){s.network=b.dataset.network;s.allowance=0;persist();closeModal();render();return}
if(b.dataset.amount){s.amount=orderMode==='sell'?Math.floor(s.available*Number(b.dataset.amount))/100:Number(b.dataset.amount);persist();$('#order').innerHTML=order();return}
if(b.dataset.mode){orderMode=b.dataset.mode;s.phase=0;s.amount=orderMode==='sell'?Math.floor(s.available*100)/100:250;persist();$('#order').innerHTML=order();return}
if(b.dataset.period){period=b.dataset.period;render();return}if(b.dataset.style){chartStyle=b.dataset.style;render();return}if(b.dataset.months){projectionMonths=Number(b.dataset.months);render();return}
if(b.dataset.stakeMode){stakeMode=b.dataset.stakeMode;stakeAmount=Math.min(1000,stakeMode==='unstake'?s.staked:s.available);$('#stake-order').innerHTML=stakeOrder();return}if(b.dataset.tab){advancedTab=b.dataset.tab;render();return}
if(b.dataset.slippage){s.slippage=Number(b.dataset.slippage);persist();if($('#modal').open)settingsModal();else render();return}
switch(b.dataset.action){case'scene-motion':{const shell=$('.token-landing');const paused=shell.classList.toggle('motion-paused');b.setAttribute('aria-label',paused?'Play animation':'Pause animation');b.innerHTML=paused?'<svg viewBox="0 0 24 24" fill="currentColor"><path d="m9 5 11 7-11 7z"/></svg>':'<svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 6h3v12H8zm5 0h3v12h-3z"/></svg>';break;}case'close':closeModal();break;case'theme':setTheme(theme==='dark'?'light':'dark');{const u=new URL(location.href);u.searchParams.set('theme',theme);historyReplace(u)}break;case'choose-source':sourcePicker(fundingFilter,'pay');break;case'choose-output':sourcePicker('STRATO','receive');break;case'reverse-pair':reversePair();break;case'wallet':walletMenu();break;case'begin':begin();break;case'choose-network':chooseNetwork();break;case'edit-amount':s.phase=0;s.swapQuote=null;persist();render();break;case'fund':fund();break;case'back-to-swap':s.sourceId=settlement().id;s.swapQuote=null;s.network='STRATO';s.phase=0;persist();render();break;case'resume-fund':request(source().native||hasAllowance()?'bridge':'allow');break;case'confirm-swap':if(balanceOf(settlement())+1e-9<(s.swapQuote?.payQty||0)){toast('Not enough '+source().asset);break}request('swap');break;case'confirm-buy':if((balanceOf(settlement())*settlement().rate)<s.amount){toast('Not enough '+source().asset+' to complete this purchase.');break}request('buy');break;case'sign':perform();break;case'cancel-sign':if(tx.type==='swap'){closeModal();toast('Swap cancelled. Your '+source().asset+' stays in your wallet.');break}closeModal();toast(tx.type==='buy'?'Purchase cancelled. Your '+source().asset+' stays in your wallet.':'Request cancelled. Your progress is saved.');break;case'go-stake':go('stake');break;case'go-portfolio':go('portfolio');break;case'go-trade':go('trade');break;case'buy-more':s.phase=0;s.swapQuote=null;s.amount=250;s.payQuantity=250/assetRate(source());persist();render();break;case'trade-settings':settingsModal();break;case'disconnect':s.wallet=null;persist();closeModal();render();toast('Wallet disconnected');break;case'stake-max':stakeAmount=Math.floor((stakeMode==='unstake'?s.staked:s.available)*100)/100;$('#stake-order').innerHTML=stakeOrder();updateStakeCalc();break;case'review-stake':if(!s.wallet){connect();break}if(!Number.isFinite(stakeAmount)||stakeAmount<=0||stakeAmount>(stakeMode==='unstake'?s.staked:s.available)){$('#stake-error').textContent='Enter an amount within your available balance.';$('#stake-error').hidden=false;break}request(stakeMode);break;case'claim':if(rewards()>0)request('claim');break;case'restake':if(rewards()>0)request('restake');break;case'validator':modal(heading('Your Validator')+`<div class="token-heading" style="margin-top:25px">${token()}<div><h1 style="font-size:19px">STRATO Validator 01</h1><span class="pill">Active</span></div></div>${dataRow('Delegator APY','9.70%')}${dataRow('Commission','Included in displayed APY')}${dataRow('Unstaking period','7 days')}<div class="modal-actions"><button class="primary" data-action="close">Continue With This Validator</button></div>`);break;case'bridge-tab':advancedTab='bridge';go('advanced');break;case'standalone-bridge':if(!s.wallet){connect();break}{let amount=Number($('#bridge-amount').value);if(!Number.isFinite(amount)||amount<=0||amount>10000){$('#bridge-error').hidden=false;break}s.amount=amount;s.payQuantity=amount;s.sourceId=$('#bridge-network').value.toLowerCase()+'-usdc';s.network=source().network;s.phase=0;persist();request(hasAllowance()?'bridge':'allow',{standalone:true});break}case'add-lp':if(!s.wallet){connect();break}{let amount=Number($('#lp-amount').value);if(!Number.isFinite(amount)||amount<=0||amount/2>s.usdst||amount/2/PRICE>s.available){$('#lp-error').textContent='You need both '+num(amount/2/PRICE)+' STRATO and '+num(amount/2)+' USDST for this deposit.';$('#lp-error').hidden=false;break}request('lp',{amount});break}case'remove-lp':request('remove');break;case'export-activity':{let csv='Type,Amount,Asset,Time\n'+s.history.map(a=>[a.type,a.amount,a.asset,new Date(a.time).toISOString()].join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='STRATO Transactions.csv';a.click();URL.revokeObjectURL(a.href);break}case'reset':modal(heading('Reset This Session?')+`<p class="modal-sub">This clears the current balances, positions and transaction history.</p><button class="primary" data-action="confirm-reset">Reset Session</button><button class="secondary" data-action="close" style="margin-top:10px">Cancel</button>`);break;case'confirm-reset':s={...initial,rewardStart:Date.now(),history:[],unbond:[]};persist();closeModal();render();toast('Session reset');break}});
setInterval(()=>{
 if(document.hidden)return;
 const previous=PRICE;PRICE=StratoMarket.tick();
 if(page==='trade'){
  if(!hoveringPrice){const c=$('#main-chart');if(c)c.innerHTML=StratoMarket.render(period,chartStyle,310);const p=$('#chart-price');if(p){p.textContent=money4(PRICE);p.classList.remove('tick-up','tick-down');void p.offsetWidth;p.classList.add(PRICE>=previous?'tick-up':'tick-down')}}
  const change=$('#price-change');if(change)change.innerHTML=marketChange();const labels=$('#market-time-labels');if(labels)labels.innerHTML=marketLabels();
  if(s.phase===0)updateSwapEstimate()
 }
 if(page==='stake'){let el=$('#live-rewards');if(el)el.textContent=num(rewards(),6);let usd=$('#reward-dollars');if(usd)usd.textContent='≈ '+money(rewards()*PRICE)}
},1400);
function historyReplace(url){window.history.replaceState(null,'',url)}
if(query.has('version')&&sessionStorage.getItem('strato-entry-variant')!==variant){s.phase=0;sessionStorage.setItem('strato-entry-variant',variant)}
if(s.phase>0&&s.phase<4&&!s.swapQuote)s.phase=0;if(source().asset===output().asset)s.outputId=source().asset==='STRATO'?'strato-usdc':'strato-strato';if(!Number.isFinite(s.payQuantity))s.payQuantity=s.amount/assetRate(source());refreshAmount();
setTheme(theme);
render();
